import json
from fractions import Fraction as F

# Subquestion 1: c = 20/(-24) - (2 + -3)
c = F(20, -24) - (2 + (-3))

# Subquestion 2: f(x) = x^4/16 + 1 + x^2/8 + 0*x - c*x^3
# Coefficients of f as {power: coefficient}
f_coeffs = {4: F(1, 16), 3: -c, 2: F(1, 8), 1: F(0), 0: F(1)}

# k(x) = f'(x): coefficient of x^(n-1) is n * a_n
k_coeffs = {n - 1: n * a for n, a in f_coeffs.items() if n >= 1}
k_coeffs = {p: k_coeffs.get(p, F(0)) for p in range(0, 4)}

def k_eval(x):
    return sum(k_coeffs[p] * x**p for p in k_coeffs)

# Candidate factorization: k(x) = (1/4) * x * (x - 1)**2
def candidate(x):
    return F(1, 4) * x * (x - 1)**2

# Exhaustive check on a finite rational grid (a cubic is fixed by 4 points,
# so agreement on this grid confirms the identity)
grid = [F(n, d) for d in range(1, 7) for n in range(-12, 13)]
grid = sorted(set(grid))
matches = all(k_eval(x) == candidate(x) for x in grid)

# Roots of k from the factorization, with multiplicities
roots = [F(0), F(1), F(1)]

if matches and c == F(1, 6):
    final_answer = "k(s) = (1/4) * s * (s - 1)**2"
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "c": str(c),
    "k_coefficients_desc": {str(p): str(k_coeffs[p]) for p in sorted(k_coeffs, reverse=True)},
    "grid_points_checked": len(grid),
    "factorization_matches_on_grid": matches,
    "roots_with_multiplicity": [str(r) for r in roots],
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
